"""Metrics collection and reporting."""

from __future__ import annotations

import time
from typing import Any


class Counter:
    def __init__(self, name: str, labels: dict[str, str] | None = None) -> None:
        self.name = name
        self.labels = labels or {}
        self._value = 0

    def inc(self, amount: int = 1) -> None:
        self._value += amount

    def get(self) -> int:
        return self._value

    def to_dict(self) -> dict[str, Any]:
        return {
            "metric_type": "counter",
            "name": self.name,
            "labels": self.labels,
            "value": self._value,
        }


class Gauge:
    def __init__(self, name: str, labels: dict[str, str] | None = None) -> None:
        self.name = name
        self.labels = labels or {}
        self._value = 0.0

    def set(self, value: float) -> None:
        self._value = value

    def get(self) -> float:
        return self._value

    def to_dict(self) -> dict[str, Any]:
        return {
            "metric_type": "gauge",
            "name": self.name,
            "labels": self.labels,
            "value": self._value,
        }


class Histogram:
    def __init__(self, name: str, buckets: list[float], labels: dict[str, str] | None = None) -> None:
        self.name = name
        self.buckets = buckets
        self.labels = labels or {}
        self._values: list[float] = []

    def observe(self, value: float) -> None:
        self._values.append(value)

    def count(self) -> int:
        return len(self._values)

    def sum(self) -> float:
        return sum(self._values)

    def avg(self) -> float:
        if not self._values:
            return 0.0
        return self.sum() / len(self._values)

    def percentile(self, p: float) -> float:
        if not self._values:
            return 0.0
        sorted_vals = sorted(self._values)
        idx = int(len(sorted_vals) * p / 100.0)
        return sorted_vals[idx]

    def to_dict(self) -> dict[str, Any]:
        return {
            "metric_type": "histogram",
            "name": self.name,
            "labels": self.labels,
            "buckets": self.buckets,
            "count": self.count(),
            "sum": self.sum(),
            "avg": self.avg(),
            "p50": self.percentile(50),
            "p95": self.percentile(95),
            "p99": self.percentile(99),
        }


class Registry:
    def __init__(self) -> None:
        self._counters: dict[str, Counter] = {}
        self._gauges: dict[str, Gauge] = {}
        self._histograms: dict[str, Histogram] = {}

    def counter(self, name: str, labels: dict[str, str] | None = None) -> Counter:
        key = f"{name}:{sorted(labels.items()) if labels else ''}"
        if key not in self._counters:
            self._counters[key] = Counter(name, labels)
        return self._counters[key]

    def gauge(self, name: str, labels: dict[str, str] | None = None) -> Gauge:
        key = f"{name}:{sorted(labels.items()) if labels else ''}"
        if key not in self._gauges:
            self._gauges[key] = Gauge(name, labels)
        return self._gauges[key]

    def histogram(self, name: str, buckets: list[float] | None = None, labels: dict[str, str] | None = None) -> Histogram:
        if buckets is None:
            buckets = [10, 50, 100, 500, 1000, 5000]
        key = f"{name}:{sorted(labels.items()) if labels else ''}"
        if key not in self._histograms:
            self._histograms[key] = Histogram(name, buckets, labels)
        return self._histograms[key]

    def to_dict(self) -> dict[str, Any]:
        result: dict[str, Any] = {}
        for c in self._counters.values():
            result[c.name] = c.to_dict()
        for g in self._gauges.values():
            result[g.name] = g.to_dict()
        for h in self._histograms.values():
            result[h.name] = h.to_dict()
        return result


_registry: Registry | None = None


def get_registry() -> Registry:
    global _registry
    if _registry is None:
        _registry = Registry()
    return _registry
EOF"}

