"""CSV data source for ingesting records from CSV files."""

from __future__ import annotations

import csv
import os
from typing import Iterator, Any
from src.models import Record


def _coerce_row(row: dict[str, str]) -> dict[str, Any]:
    result: dict[str, Any] = {}
    for k, v in row.items():
        result[k] = _try_numeric(v)
    return result


def _try_numeric(value: str) -> str | int | float:
    if not value or not isinstance(value, str):
        return value
    try:
        return int(value)
    except ValueError:
        pass
    try:
        return float(value)
    except ValueError:
        pass
    parsed = _try_parse_date(value)
    if parsed:
        return parsed
    return value


def _try_parse_date(value: str) -> str | None:
    # simplistic date parsing: YYYY-MM-DD or YYYY-MM-DD HH:MM:SS
    if len(value) < 10:
        return None
    if value[4] == '-' and value[7] == '-':
        # could be a date
        return value
    return None


class CsvSource:
    def __init__(self, path: str) -> None:
        self.path = path
        if not os.path.exists(path):
            raise FileNotFoundError(f"CSV file not found: {path}")

    def iter_records(self) -> Iterator[Record]:
        with open(self.path, newline='', encoding='utf-8') as f:
            reader = csv.DictReader(f)
            for row in reader:
                coerced = _coerce_row(row)
                yield Record.from_dict(coerced)

    def get_common_schema(self) -> dict[str, str]:
        with open(self.path, newline='', encoding='utf-8') as f:
            sample = f.read(8192)
            dialect = csv.Sniffer().sniff(sample)
            f.seek(0)
            reader = csv.reader(f, dialect)
            header = next(reader, None)
            if not header:
                return {}
            # For simplicity, assume all fields are strings
            return {field: "str" for field in header}

    def count(self) -> int:
        with open(self.path, newline='', encoding='utf-8') as f:
            reader = csv.reader(f)
            return sum(1 for _ in reader) - 1  # subtract header
EOF"}

