"""Database connection pool and utilities."""

from __future__ import annotations

import sqlite3
from typing import Any, Iterator
from contextlib import contextmanager


class ConnectionPool:
    def __init__(self, db_path: str, max_connections: int = 5) -> None:
        self.db_path = db_path
        self.max_connections = max_connections
        self._pool: list[sqlite3.Connection] = []

    def _create_connection(self) -> sqlite3.Connection:
        conn = sqlite3.connect(self.db_path, check_same_thread=False)
        conn.row_factory = sqlite3.Row
        return conn

    def acquire(self) -> sqlite3.Connection:
        if self._pool:
            return self._pool.pop()
        return self._create_connection()

    def release(self, conn: sqlite3.Connection) -> None:
        if len(self._pool) < self.max_connections:
            self._pool.append(conn)
        else:
            conn.close()

    def close(self) -> None:
        for conn in self._pool:
            conn.close()
        self._pool.clear()


_pool: ConnectionPool | None = None


def init_pool(db_path: str, max_connections: int = 5) -> ConnectionPool:
    global _pool
    if _pool is None:
        _pool = ConnectionPool(db_path, max_connections)
    return _pool


def get_pool() -> ConnectionPool | None:
    return _pool


def get_connection() -> sqlite3.Connection | None:
    if _pool is None:
        return None
    return _pool.acquire()


def release_connection(conn: sqlite3.Connection | None) -> None:
    if conn is None or _pool is None:
        return
    _pool.release(conn)


def execute_query(query: str, params: tuple[Any, ...] | None = None) -> list[sqlite3.Row]:
    if params is None:
        params = ()
    conn = get_connection()
    if conn is None:
        raise RuntimeError("Connection pool not initialized")
    try:
        cursor = conn.execute(query, params)
        if query.strip().lower().startswith("select"):
            rows = cursor.fetchall()
        else:
            conn.commit()
            rows = []
        return rows
    finally:
        release_connection(conn)
EOF"}

