"""Transform pipelines for records."""

from __future__ import annotations

from typing import Callable, Any
from src.models import Record


Transform = Callable[[Record], Record]


def passthrough() -> Transform:
    def transform(record: Record) -> Record:
        return record
    return transform


def map_fields(field_map: dict[str, str]) -> Transform:
    def transform(record: Record) -> Record:
        new_data: dict[str, Any] = {}
        for old_key, new_key in field_map.items():
            if old_key in record.data:
                new_data[new_key] = record.data[old_key]
        return Record(
            source=record.source,
            data=new_data,
            timestamp=record.timestamp,
            record_id=record.record_id,
            tags=list(record.tags),
            metadata=dict(record.metadata),
        )
    return transform


def drop_fields(fields: set[str]) -> Transform:
    def transform(record: Record) -> Record:
        new_data = {k: v for k, v in record.data.items() if k not in fields}
        return Record(
            source=record.source,
            data=new_data,
            timestamp=record.timestamp,
            record_id=record.record_id,
            tags=list(record.tags),
            metadata=dict(record.metadata),
        )
    return transform


def filter_by(fields: dict[str, Any]) -> Transform:
    def transform(record: Record) -> Record:
        match = all(record.data.get(k) == v for k, v in fields.items())
        return record if match else Record(
            source=record.source,
            data={},
            timestamp=record.timestamp,
            record_id=record.record_id,
            tags=list(record.tags),
            metadata=dict(record.metadata),
        )
    return transform


def normalize() -> Transform:
    def transform(record: Record) -> Record:
        normalized: dict[str, Any] = {}
        for k, v in record.data.items():
            if isinstance(v, dict):
                normalized[k] = str(v)
            elif isinstance(v, list):
                normalized[k] = str(v)
            else:
                normalized[k] = v
        return Record(
            source=record.source,
            data=normalized,
            timestamp=record.timestamp,
            record_id=record.record_id,
            tags=list(record.tags),
            metadata=dict(record.metadata),
        )
    return transform


def flatten() -> Transform:
    def transform(record: Record) -> Record:
        def _flatten(obj: Any, prefix: str = "") -> dict[str, Any]:
            res: dict[str, Any] = {}
            if isinstance(obj, dict):
                for k, v in obj.items():
                    new_key = f"{prefix}{k}" if not prefix else f"{prefix}.{k}"
                    res.update(_flatten(v, new_key))
            elif isinstance(obj, list):
                for i, v in enumerate(obj):
                    new_key = f"{prefix}[{i}]"
                    res.update(_flatten(v, new_key))
            else:
                res[prefix] = obj
            return res

        flattened = _flatten(record.data)
        return Record(
            source=record.source,
            data=flattened,
            timestamp=record.timestamp,
            record_id=record.record_id,
            tags=list(record.tags),
            metadata=dict(record.metadata),
        )
    return transform


def enrich_fields(extra: dict[str, Any]) -> Transform:
    def transform(record: Record) -> Record:
        new_data = {**record.data, **extra}
        return Record(
            source=record.source,
            data=new_data,
            timestamp=record.timestamp,
            record_id=record.record_id,
            tags=list(record.tags),
            metadata=dict(record.metadata),
        )
    return transform


def compose(*transforms: Transform) -> Transform:
    def transform(record: Record) -> Record:
        result = record
        for t in transforms:
            result = t(result)
        return result
    return transform


_registry: dict[str, Transform] = {}


def register(name: str, transform: Transform) -> None:
    _registry[name] = transform


def get_transform(name: str) -> Transform:
    return _registry[name]


register("passthrough", passthrough())
register("normalize", normalize())
register("flatten", flatten())
EOF"}

