"""REST API data source for ingesting records."""

from __future__ import annotations

import time
from typing import Iterator, Any, cast
import requests
from src.models import Record, BatchResult


def fetch_page(url: str, headers: dict[str, str] | None = None, params: dict[str, Any] | None = None) -> dict[str, Any]:
    resp = requests.get(url, headers=headers, params=params or {}, timeout=30)
    resp.raise_for_status()
    return cast(dict[str, Any], resp.json())


def build_auth_headers(auth_type: str, credentials: dict[str, str]) -> dict[str, str]:
    headers: dict[str, str] = {}
    if auth_type == "bearer":
        token = credentials.get("token", "")
        headers["Authorization"] = f"Bearer {token}"
    elif auth_type == "basic":
        import base64

        username = credentials.get("username", "")
        password = credentials.get("password", "")
        creds = base64.b64encode(f"{username}:{password}".encode()).decode()
        headers["Authorization"] = f"Basic {creds}"
    return headers


class ApiSource:
    def __init__(self, base_url: str, endpoint: str) -> None:
        self.base_url = base_url.rstrip("/")
        self.endpoint = endpoint.lstrip("/")

    def url(self) -> str:
        return f"{self.base_url}/{self.endpoint}"

    def fetch_page(self, page: int = 1, per_page: int = 100) -> dict[str, Any]:
        return fetch_page(self.url(), params={"page": page, "per_page": per_page})

    def iter_records(self) -> Iterator[Record]:
        page = 1
        while True:
            data = self.fetch_page(page=page)
            if not data:
                break
            page += 1
            results = data.get("results", data.get("data", []))
            if not results:
                break
            for item in results:
                record = Record.from_dict(item)
                yield record


def fetch_all_pages(source: ApiSource, max_pages: int = 10) -> list[Record]:
    records: list[Record] = []
    for i in range(max_pages):
        page = source.fetch_page(page=i + 1)
        results = cast(list[Any], page.get("results", page.get("data", [])))
        if not results:
            break
        for item in results:
            record = Record.from_dict(item)
            records.append(record)
        if len(results) < 100:
            break
    return records


def ingest_from_api(config: dict[str, Any], metrics: Any = None) -> Iterator[Record]:
    batch = BatchResult()
    base_url = config.get("base_url", "")
    endpoint = config.get("endpoint", "")
    headers = config.get("headers")
    auth = config.get("auth")
    try:
        src = ApiSource(base_url, endpoint)
        if auth:
            auth_type = auth.get("type", "bearer")
            headers = build_auth_headers(auth_type, auth.get("credentials", {}))
        for rec in fetch_all_pages(src):
            yield rec  # caller tracks batch
            batch.add_success()
            if metrics:
                metrics.counter("api_records_read").inc()
    except Exception as e:
        batch.add_failure(str(e))
        if metrics:
            metrics.counter("api_read_failures").inc()
EOF"}

